@SpringBootTest @AutoConfigureMockMvc @Transactional
@EnabledIfEnvironmentVariable(named="LEPETSE_DB_TEST",matches="true")
class AdminPricingWorkflowTest {
 @Autowired MockMvc http;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;
 long request(String type){long c=db.queryForObject("insert into customer(organisation,contact_name,email,phone) values ('Pricing test','Sample buyer','buyer@example.invalid','000') returning id",Long.class);long r=db.queryForObject("insert into rfq(reference,customer_id,buyer_type,purchase_type,status,contact_snapshot,submitted_at) values (?, ?,?,'once_off','submitted','{\"organisation\":\"Pricing test\",\"contact\":\"Sample buyer\",\"email\":\"buyer@example.invalid\"}',now()) returning id",Long.class,"PRICING-"+UUID.randomUUID(),c,type);db.update("insert into rfq_item(rfq_id,description,quantity,ordering_unit,product_id) values (?,'Blue pens',75,'Each',?)",r,product());return r;}
 long product(){return db.queryForObject("select id from product where active order by id limit 1",Long.class);}
 long item(long r){return db.queryForObject("select id from rfq_item where rfq_id=?",Long.class,r);}
 long offer(String price,int units,String match){long sup=db.queryForObject("insert into supplier(name) values (?) returning id",Long.class,"PRIVATE SUPPLIER "+UUID.randomUUID());long q=db.queryForObject("insert into supplier_quote(supplier_id,reference,quote_date,valid_until,created_by) values (?,'PRIVATE-SOURCE',current_date,current_date+14,'owner') returning id",Long.class,sup);return db.queryForObject("insert into supplier_quote_line(quote_id,supplier_sku,description,product_id,match_type,pack_label,units_per_pack,pack_price_ex_vat,quoted_packs) values (?,'SECRET-SKU','PRIVATE SOURCE',?,?,'Box',?,?,1) returning id",Long.class,q,product(),match,units,new BigDecimal(price));}
 Map<String,Object> source(long r,long offer,String price,long version){return Map.of("version",version,"lines",List.of(Map.of("itemId",item(r),"productId",product(),"supplierLineId",offer,"conversion",1,"expectedPackPrice",price,"alternativeConfirmed",false)));}
 org.springframework.test.web.servlet.ResultActions postW(long r,String path,Object body)throws Exception{return http.perform(post("/api/admin/rfqs/"+r+"/pricing"+path).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(body)));}
 long approve(long r)throws Exception{long o=offer("189",60,"exact");postW(r,"/sourcing",source(r,o,"189",0)).andExpect(status().isOk());postW(r,"/approve",Map.of("version",1)).andExpect(status().isOk());return o;}
 Map<String,Object> sell(long r,int version){return Map.of("version",version,"approvalVersion",1,"lines",List.of(Map.of("itemId",item(r),"description","Customer blue pens","markup",25,"sellingPrice",6.30)),"transport",20,"vatRate",0.15,"validUntil",LocalDate.now().plusDays(7).toString(),"terms","Payment on agreed terms.");}
 long finalise(long r)throws Exception{postW(r,"/quote",sell(r,1)).andExpect(status().isOk());return json.readTree(postW(r,"/finalise",Map.of("version",2,"submissionKey",UUID.randomUUID())).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get("id").asLong();}
 @Test void supplierLineEditingValidatesAndStaysWithinItsQuote()throws Exception{long line=offer("189",60,"exact"),quote=db.queryForObject("select quote_id from supplier_quote_line where id=?",Long.class,line);var body=new LinkedHashMap<String,Object>(Map.of("sku","UPDATED","description","Updated blue pens","productId",product(),"matchType","exact","packLabel","Box of 50","unitsPerPack",50,"packPrice",170,"quotedPacks",2,"availability","In stock","leadTime","2 days"));String url="/api/admin/supply/quotes/"+quote+"/lines/"+line;http.perform(put(url).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(body))).andExpect(status().isOk());assertThat(db.queryForObject("select pack_price_ex_vat from supplier_quote_line where id=?",BigDecimal.class,line)).isEqualByComparingTo("170");long otherLine=offer("200",50,"exact"),otherQuote=db.queryForObject("select quote_id from supplier_quote_line where id=?",Long.class,otherLine);http.perform(put("/api/admin/supply/quotes/"+otherQuote+"/lines/"+line).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(body))).andExpect(status().isNotFound());body.put("unitsPerPack",0);http.perform(put(url).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(body))).andExpect(status().isBadRequest());}
 @Test void supplierProfilesAndLatestCatalogueRetainOldPriceLists()throws Exception{var profile=new LinkedHashMap<String,Object>();profile.put("name","Directory supplier "+UUID.randomUUID());profile.put("contactName","Contact");profile.put("email","supplier@example.invalid");profile.put("phone","000");profile.put("address","Address");profile.put("paymentTerms","COD");profile.put("deliveryNotes","Confirm charges");long supplier=json.readTree(http.perform(post("/api/admin/supply/suppliers").with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(profile))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get("id").asLong();http.perform(get("/api/admin/supply/suppliers/"+supplier).with(user("owner").roles("ADMIN"))).andExpect(jsonPath("$.contact_name").value("Contact"));long old=db.queryForObject("insert into supplier_quote(supplier_id,reference,quote_date,created_by) values (?,'OLD',current_date-1,'owner') returning id",Long.class,supplier),latest=db.queryForObject("insert into supplier_quote(supplier_id,reference,quote_date,created_by) values (?,'NEW',current_date,'owner') returning id",Long.class,supplier);for(long q:List.of(old,latest))db.update("insert into supplier_quote_line(quote_id,supplier_sku,description,match_type,pack_label,units_per_pack,pack_price_ex_vat,quoted_packs) values (?,'CODE-1','Paper','unmatched','Ream',1,?,1)",q,q==old?80:90);db.update("insert into supplier_quote_line(quote_id,supplier_sku,description,match_type,pack_label,units_per_pack,pack_price_ex_vat,quoted_packs) values (?,'CODE-2','Pens','unmatched','Box',50,170,1)",old);http.perform(get("/api/admin/supply/suppliers/"+supplier+"/catalogue").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.length()").value(2)).andExpect(jsonPath("$[0].pack_price_ex_vat").value(90)).andExpect(jsonPath("$[1].missing_from_latest").value(true));assertThat(db.queryForObject("select count(*) from supplier_quote_line where quote_id=?",Integer.class,old)).isEqualTo(2);profile.put("contactName","Updated contact");http.perform(put("/api/admin/supply/suppliers/"+supplier).with(user("owner").roles("ADMIN")).with(csrf()).contentType("application/json").content(json.writeValueAsBytes(profile))).andExpect(status().isOk());http.perform(get("/api/admin/supply/suppliers/"+supplier)).andExpect(status().isUnauthorized());}
 @Test void catalogueCaptureKeepsProductLinkAndRejectsUnknownProduct()throws Exception{long r=request("business"),p=product();postW(r,"/items",Map.of("productId",p,"description","Input","quantity",3,"unit","Input unit")).andExpect(status().isOk());assertThat(db.queryForObject("select count(*) from rfq_item where rfq_id=? and product_id=? and quantity=3 and description=(select name from product where id=?) and ordering_unit=(select ordering_unit from product where id=?)",Integer.class,r,p,p,p)).isEqualTo(1);postW(r,"/items",Map.of("productId",Long.MAX_VALUE,"description","Input","quantity",3,"unit","Each")).andExpect(status().isBadRequest());}
 @Test void sourcingApprovalIsSeparateAndCalculatesWholePackCosts()throws Exception{long r=request("business"),o=offer("189",60,"exact");postW(r,"/quote",sell(r,0)).andExpect(status().isConflict());postW(r,"/sourcing",source(r,o,"189",0)).andExpect(status().isOk());postW(r,"/sourcing",source(r,o,"189",0)).andExpect(status().isConflict());postW(r,"/approve",Map.of("version",1)).andExpect(status().isOk());http.perform(get("/api/admin/rfqs/"+r+"/pricing").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.approval.lines[0].purchaseCost").value(378)).andExpect(jsonPath("$.approval.lines[0].unitCost").value(5.04)).andExpect(jsonPath("$.approval.lines[0].extraUnits").value(45));assertThat(db.queryForObject("select status from rfq where id=?",String.class,r)).isEqualTo("approved");assertThat(db.queryForObject("select count(*) from quotation where rfq_id=?",Integer.class,r)).isZero();postW(r,"/sourcing",source(r,o,"189",1)).andExpect(status().isConflict());}
 @Test void approvedQueueIncludesSchoolsAndExcludesUnapprovedRequests()throws Exception{long r=request("schools");approve(r);long other=request("government");http.perform(get("/api/admin/rfqs?stage=approved&buyer=schools").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].id").value(r));http.perform(get("/api/admin/rfqs?stage=sourcing&buyer=government").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.items[*].id").value(org.hamcrest.Matchers.hasItem((int)other)));}
 @Test void approvalRejectsExpiredChangedForeignAndUnapprovedAlternativeSources()throws Exception{long r=request("government"),other=request("business"),o=offer("10",1,"exact");postW(r,"/sourcing",source(other,o,"10",0)).andExpect(status().isBadRequest());postW(r,"/sourcing",source(r,o,"10",0)).andExpect(status().isOk());db.update("update supplier_quote_line set pack_price_ex_vat=12 where id=?",o);postW(r,"/approve",Map.of("version",1)).andExpect(status().isConflict());postW(r,"/sourcing",source(r,o,"12",1)).andExpect(status().isOk());db.update("update supplier_quote set quote_date=current_date-10,valid_until=current_date-1 where id=(select quote_id from supplier_quote_line where id=?)",o);postW(r,"/approve",Map.of("version",2)).andExpect(status().isBadRequest());db.update("update supplier_quote set valid_until=current_date+10 where id=(select quote_id from supplier_quote_line where id=?)",o);db.update("update supplier_quote_line set match_type='alternative' where id=?",o);postW(r,"/approve",Map.of("version",2)).andExpect(status().isBadRequest());}
 @Test void finalQuoteIsPrivateImmutableAndSendingIsNeverAssumed()throws Exception{long r=request("business");approve(r);long q=finalise(r);http.perform(get("/api/admin/rfqs/"+r+"/pricing/quotations/"+q).with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(566.38)).andExpect(jsonPath("$.vatTotal").value(73.88));assertThat(db.queryForObject("select status from rfq where id=?",String.class,r)).isEqualTo("approved");byte[] bytes=http.perform(get("/api/admin/rfqs/"+r+"/pricing/quotations/"+q+"/pdf").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();try(var pdf=Loader.loadPDF(bytes)){assertThat(new PDFTextStripper().getText(pdf)).contains("Customer blue pens","R 566,38").doesNotContain("PRIVATE SUPPLIER","SECRET-SKU","markup","5.04");}http.perform(get("/api/admin/rfqs/"+r+"/pricing/quotations/"+q+"/email-draft").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("To: buyer@example.invalid"))).andExpect(content().string(org.hamcrest.Matchers.containsString("application/pdf")));assertThat(db.queryForObject("select emailed_at from quotation where id=?",Object.class,q)).isNull();postW(r,"/quotations/"+q+"/record-sent",Map.of("recipient","wrong@example.invalid")).andExpect(status().isBadRequest());postW(r,"/quotations/"+q+"/record-sent",Map.of("recipient","buyer@example.invalid")).andExpect(status().isOk());assertThat(db.queryForObject("select status from rfq where id=?",String.class,r)).isEqualTo("quoted");assertThat(db.queryForObject("select count(*) from product_price_decision",Integer.class)).isZero();}
 @Test void revisionsAndReturnsInvalidateStaleQuotesAndRetainHistory()throws Exception{long r=request("business");approve(r);long q=finalise(r);postW(r,"/quote",sell(r,1)).andExpect(status().isConflict());postW(r,"/quote",sell(r,2)).andExpect(status().isOk());postW(r,"/quotations/"+q+"/record-sent",Map.of("recipient","buyer@example.invalid")).andExpect(status().isConflict());postW(r,"/return",Map.of("reason","Quantity needs checking")).andExpect(status().isOk());assertThat(db.queryForObject("select status from quotation where id=?",String.class,q)).isEqualTo("superseded");assertThat(db.queryForObject("select status from rfq where id=?",String.class,r)).isEqualTo("in_review");postW(r,"/finalise",Map.of("version",3,"submissionKey",UUID.randomUUID())).andExpect(status().isConflict());assertThat(db.queryForObject("select count(*) from rfq_pricing_event where rfq_id=?",Integer.class,r)).isGreaterThanOrEqualTo(3);}
 @Test void securityItemIsolationAndChangedSupplierCostsBlockFinalising()throws Exception{long r=request("business"),o=approve(r);http.perform(get("/api/admin/rfqs/"+r+"/pricing")).andExpect(status().isUnauthorized());http.perform(get("/api/admin/rfqs/"+r+"/pricing").with(user("viewer").roles("USER"))).andExpect(status().isForbidden());http.perform(post("/api/admin/rfqs/"+r+"/pricing/return").with(user("owner").roles("ADMIN")).contentType("application/json").content("{\"reason\":\"x\"}")).andExpect(status().isForbidden());postW(r,"/quote",sell(r,1)).andExpect(status().isOk());db.update("update supplier_quote_line set pack_price_ex_vat=200 where id=?",o);postW(r,"/finalise",Map.of("version",2,"submissionKey",UUID.randomUUID())).andExpect(status().isConflict());}
 @Test void finaliseIdempotencyCaptureAndCrossRequestPreview()throws Exception{long r=request("business");approve(r);postW(r,"/quote",sell(r,1)).andExpect(status().isOk());UUID key=UUID.randomUUID();long q=json.readTree(postW(r,"/finalise",Map.of("version",2,"submissionKey",key)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString()).get("id").asLong();postW(r,"/finalise",Map.of("version",2,"submissionKey",key)).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(q));assertThat(db.queryForObject("select count(*) from quotation where rfq_id=?",Integer.class,r)).isEqualTo(1);long other=request("schools");http.perform(get("/api/admin/rfqs/"+other+"/pricing/quotations/"+q).with(user("owner").roles("ADMIN"))).andExpect(status().isNotFound());postW(other,"/items",Map.of("description","Document paper","quantity",5,"unit","Ream")).andExpect(status().isOk());assertThat(db.queryForObject("select count(*) from rfq_item where rfq_id=?",Integer.class,other)).isEqualTo(2);}
 @Test void sourcingQuantityOverridesPreserveTheOriginalCustomerRequirement()throws Exception{
  long r=request("business"),o=offer("189",60,"exact");var source=new HashMap<String,Object>(source(r,o,"189",0));var line=new HashMap<String,Object>(Map.of("itemId",item(r),"productId",product(),"supplierLineId",o,"conversion",1,"quantity",100,"expectedPackPrice",189,"alternativeConfirmed",false));source.put("lines",List.of(line));postW(r,"/sourcing",source).andExpect(status().isOk());postW(r,"/approve",Map.of("version",1)).andExpect(status().isOk());assertThat(db.queryForObject("select quantity from rfq_item where rfq_id=?",Integer.class,r)).isEqualTo(75);long q=finalise(r);http.perform(get("/api/admin/rfqs/"+r+"/pricing/quotations/"+q).with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].quantity").value(100));
 }
 @Test void roundingMustNotHideSellingBelowTheApprovedCost()throws Exception{
  long r=request("business"),o=offer("170",50,"exact");postW(r,"/sourcing",source(r,o,"170",0)).andExpect(status().isOk());postW(r,"/approve",Map.of("version",1)).andExpect(status().isOk());var d=new HashMap<String,Object>(sell(r,1));d.put("lines",List.of(Map.of("itemId",item(r),"description","Pens","markup",0,"sellingPrice",4.53)));postW(r,"/quote",d).andExpect(status().isBadRequest());d.put("lines",List.of(Map.of("itemId",item(r),"description","Pens","markup",0,"sellingPrice",4.54)));postW(r,"/quote",d).andExpect(status().isOk());
 }

 @Test void emailAttachmentMatchesDownloadedLayout()throws Exception{long r=request("business");approve(r);long q=finalise(r);String path="/api/admin/rfqs/"+r+"/pricing/quotations/"+q;byte[] direct=http.perform(get(path+"/pdf").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();String mime=http.perform(get(path+"/email-draft").with(user("owner").roles("ADMIN"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String part=mime.substring(mime.indexOf("Content-Type: application/pdf"));String marker="Content-Transfer-Encoding: base64\r\n\r\n";part=part.substring(part.indexOf(marker)+marker.length());byte[] attachment=Base64.getMimeDecoder().decode(part.substring(0,part.indexOf("\r\n--")));try(var a=Loader.loadPDF(direct);var b=Loader.loadPDF(attachment)){assertThat(new PDFTextStripper().getText(a)).isEqualTo(new PDFTextStripper().getText(b));assertThat(new PDFTextStripper().getText(b)).contains("CUSTOMER","DELIVERY ADDRESS","QUOTATION DETAILS");}}
}
